function parseRow(row) {
 const call=row.tool_calls[1]; if (!call.complete||call.stdout.utf8===null||call.stderr.bytes) throw Error("otool incomplete/diagnostic "+row.path);
 const text=call.stdout.utf8, escaped=row.path.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
 const heads=[...text.matchAll(new RegExp("^"+escaped+" \\(architecture ([^)]+)\\):\\n","gm"))];
 if(heads.length!==2||heads[0].index!==0)throw Error("unexpected slices");
 const slices=heads.map((h,i)=>{
  const body=text.slice(h.index+h[0].length,heads[i+1]?.index??text.length), header=body.match(/^Mach header\n[^\n]+\n\s*(0x[0-9a-f]+)\s+(\d+)\s+(\d+)\s+(0x[0-9a-f]+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(0x[0-9a-f]+)\n/);
  if(!header)throw Error("header");
  const commands=[...body.matchAll(/^Load command (\d+)\n\s*cmd ([A-Z0-9_]+)\n\s*cmdsize (\d+)\n/gm)].map((m,j,a)=>{
   const block=body.slice(m.index,a[j+1]?.index??body.length),kind=m[2],name=block.match(/^\s+(?:name|path) (.+) \(offset (\d+)\)$/m);
   return {index:+m[1],kind,bytes:+m[3],...(name?{name:name[1],name_offset:+name[2]}:{}),
    ...(kind==="LC_BUILD_VERSION"?{minimum_os:block.match(/^\s+minos (.+)$/m)?.[1],sdk:block.match(/^\s+sdk (.+)$/m)?.[1]}:{})};
  });
  if(commands.length!==+header[6]||commands.some((c,j)=>c.index!==j)||commands.reduce((n,c)=>n+c.bytes,0)!==+header[7])throw Error("command coverage");
  const dylibKinds=["LC_ID_DYLIB","LC_LOAD_DYLIB","LC_LOAD_WEAK_DYLIB","LC_REEXPORT_DYLIB","LC_LAZY_LOAD_DYLIB","LC_LOAD_UPWARD_DYLIB"];
  const listing=[...body.matchAll(/^\t(.+) \(compatibility version [^\n]+\)$/gm)].map(m=>m[1]);
  if(JSON.stringify(listing)!==JSON.stringify(commands.filter(c=>dylibKinds.includes(c.kind)).map(c=>c.name)))throw Error("-L disagreement");
  const recognized=["LC_SEGMENT_64","LC_SYMTAB","LC_DYSYMTAB","LC_UUID","LC_BUILD_VERSION","LC_SOURCE_VERSION","LC_MAIN","LC_FUNCTION_STARTS","LC_DATA_IN_CODE","LC_CODE_SIGNATURE","LC_DYLD_INFO_ONLY","LC_DYLD_CHAINED_FIXUPS","LC_DYLD_EXPORTS_TRIE",...dylibKinds,"LC_LOAD_DYLINKER","LC_RPATH","LC_DYLD_ENVIRONMENT"];
  const unknown=commands.filter(c=>!recognized.includes(c.kind));
  return {architecture:h[1],header:{magic:header[1],cpu_type:+header[2],cpu_subtype:+header[3],caps:header[4],filetype:+header[5],ncmds:+header[6],sizeofcmds:+header[7],flags:header[8]},commands,listing,unknown_commands:unknown};
 });
 if(JSON.stringify(slices.map(s=>s.architecture))!==JSON.stringify(["x86_64","arm64"]))throw Error("architecture-set");
 return {path:row.path,identity:row.identity,slices};
}
